function dedupe(arr) {
  const seen = new Set();
  const result = [];
  for (const obj of arr) {
    if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
      result.push(obj);
      continue;
    }
    const keys = Object.keys(obj).sort();
    let json = '{';
    for (let i = 0; i < keys.length; i++) {
      const k = keys[i];
      if (i > 0) json += ',';
      json += JSON.stringify(k) + ':' + JSON.stringify(obj[k]);
    }
    json += '}';
    if (!seen.has(json)) {
      seen.add(json);
      result.push(obj);
    }
  }
  return result;
}

